201			}
202			if r.Version != recordVersion {
203				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
204			}
205			switch r.Status {
206			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
207			default:
208				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
209			}
210			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
211			// 恢复为只含一个作业号的列表（语义与提交时一致）。
212			deps := append([]uint64(nil), r.Dependencies...)
213			if len(deps) == 0 && r.HasDependency {
214				deps = []uint64{r.DependencyID}
215			}
216			j := &storedJob{
217				id:           r.ID,
218				submitter:    r.Submitter,
219				requestID:    r.RequestID,
220				seed:         r.Seed,
221				values:       append([]int64(nil), r.Values...),
222				dependencies: deps,
223	
224				queuedAt:   r.QueuedAt,
225				startedAt:  r.StartedAt,
226				finishedAt: r.FinishedAt,
227	
228				status:        r.Status,
229				failureReason: r.FailureReason,
230				blockerID:     r.BlockerID,
231	
232				effectiveValues: append([]int64(nil), r.EffectiveValues...),
233				archive:         r.Archive,
234			}
235			if j.status == StatusRunning {
236				j.status = StatusFailed
237				j.failureReason = "计算被中断：归档上次关闭时作业仍在运行"
238				j.blockerID = 0
239				if j.finishedAt.IsZero() {
240					j.finishedAt = time.Now().UTC()
241				}
242				j.effectiveValues = nil
243				j.archive = nil
244				// 就地重写恢复后的终态。
245				if data, err := encodeRecord(j); err == nil {
246					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
247				}
248			}
249			if j.status == StatusSucceeded && !archiveIntact(j) {
250				j.status = StatusFailed
251				j.failureReason = "归档不完整或校验值不一致，成功结果不可用"
252				if j.finishedAt.IsZero() {
253					j.finishedAt = time.Now().UTC()
254				}
255				j.effectiveValues = nil
256				j.archive = nil
257				if data, err := encodeRecord(j); err == nil {
258					_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
259				}
260			}
261			jobs = append(jobs, j)
262			if j.id > maxID {
263				maxID = j.id
264			}
265		}
266		sort.Slice(jobs, func(a, b int) bool {
267			if !jobs[a].queuedAt.Equal(jobs[b].queuedAt) {
268				return jobs[a].queuedAt.Before(jobs[b].queuedAt)
269			}
270			return jobs[a].id < jobs[b].id
271		})
272		return jobs, maxID, nil
273	}
274	
275	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
276	func archiveIntact(j *storedJob) bool {
277		a := j.archive
278		if a == nil {
279			return false
280		}
281		// 归档中的原始参数必须与记录顶层字段一致。
282		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
283			a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
284			return false
285		}
286		if a.HasDependency && a.DependencyID != depID(j) {
287			return false
288		}
289		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
290		// 由单依赖字段推导后再比较。
291		aDeps := append([]uint64(nil), a.Dependencies...)
292		if len(aDeps) == 0 && a.HasDependency {
293			aDeps = []uint64{a.DependencyID}
294		}
295		if len(aDeps) != len(j.dependencies) {
296			return false
297		}
298		for i := range j.dependencies {
299			if aDeps[i] != j.dependencies[i] {
300				return false
301			}
302		}
303		if len(a.Values) != len(j.values) {
304			return false
305		}
306		for i := range j.values {
307			if a.Values[i] != j.values[i] {
308				return false
309			}
310		}
311		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
312			return false
313		}
314		for i := range j.effectiveValues {
315			if j.effectiveValues[i] != a.EffectiveValues[i] {
316				return false
317			}
318		}
319		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
320			return false
321		}
322		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
323			return false
324		}
325		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
326			return false
327		}
328		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
329			return false
330		}
331		return true
332	}
